import json

# Load the metabolism kit
with open('compose/assets/compose/metabolism.kit.compose.json', 'r') as f:
    kit = json.load(f)

# Find the Nakagin Capsule Tower design
nakagin_design = None
for design in kit.get('designs', []):
    if design.get('guid') == '9a890dd4-0a9c-48ac-920a-9e62666465ef':
        nakagin_design = design
        break

if nakagin_design:
    # Find pieces with name 't_f1_b_c1'
    matching_pieces = []
    for piece in nakagin_design.get('pieces', []):
        if piece.get('name') == 't_f1_b_c1':
            matching_pieces.append(piece)

    print(f'Found {len(matching_pieces)} pieces with name \"t_f1_b_c1\":')
    for piece in matching_pieces:
        print(f'  GUID: {piece.get(\"guid\")}')
else:
    print('Nakagin Capsule Tower design not found')
